import os,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def transform(g):
    h=len(g); w=len(g[0])
    cells=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=0]
    if not cells: return [r[:] for r in g]
    r0=min(i for i,j in cells); r1=max(i for i,j in cells)
    c0=min(j for i,j in cells); c1=max(j for i,j in cells)
    inner=g[r0+1][c0+1]  # inner color
    out=[r[:] for r in g]
    for i in range(max(0,r0-2),min(h,r1+3)):
        for j in range(max(0,c0-2),min(w,c1+3)):
            if g[i][j]==0: out[i][j]=inner
    return out
